package com.kiroxtm.screen;

import java.util.Locale;

import com.kiroxtm.KiroxMap;
import net.minecraft.client.gui.GuiGraphicsExtractor;
import net.minecraft.client.renderer.RenderPipelines;
import net.minecraft.resources.Identifier;

/**
 * Toolbar icons. Each one is a 64x64 white-on-transparent PNG in
 * {@code assets/kirox_map/textures/gui/icons/<name>.png}, drawn scaled to any size, so the UI scale
 * only changes the size and never the design. The PNGs are generated by {@code tools/generate_icons.py};
 * replace any of them with your own artwork of the same name and size.
 */
enum ToolIcon {
	OVERWORLD, NETHER, END, GRID, SLIME, LABELS, WAYPOINT_LABELS, STRUCTURES, BIOMES, WAYPOINT, HELP,
	CLOSE, SEED, ZOOM_IN, ZOOM_OUT, CENTER, COPY, RESET, SCALE, REGEN, RELIEF;

	private static final int TEXTURE_SIZE = 64;

	private final Identifier texture = KiroxMap.id("textures/gui/icons/" + name().toLowerCase(Locale.ROOT) + ".png");

	/** Draws the icon scaled to {@code size} x {@code size} GUI pixels, tinted by {@code color} (ARGB). */
	void draw(GuiGraphicsExtractor graphics, int x, int y, int size, int color) {
		graphics.blit(RenderPipelines.GUI_TEXTURED, texture, x, y, 0f, 0f, size, size, TEXTURE_SIZE, TEXTURE_SIZE, TEXTURE_SIZE, TEXTURE_SIZE, color);
	}
}
